INSERT INTO public.news (slug, title, excerpt, body, category, cover_url, published_at) VALUES
('raccolta-olive-2026', 'Raccolta delle olive 2026: i nostri produttori si raccontano', 'Una stagione di transizione verso l''agricoltura rigenerativa e la qualità assoluta dell''olio extravergine dei Sicani.', E'## Una stagione di rinascita\n\nLa raccolta 2026 segna un punto di svolta per il consorzio. Quaranta dei nostri produttori hanno aderito al protocollo di agricoltura rigenerativa, con risultati misurabili sia sulla qualità dell''olio sia sulla salute dei suoli.\n\n### I numeri\n\n- **140+** produttori coinvolti\n- **23** comuni dei Monti Sicani\n- **+18%** di polifenoli rispetto alla media regionale\n\nUn ringraziamento ai frantoi che hanno accolto il nuovo disciplinare di molitura a freddo certificato.', 'Reportage', 'https://images.unsplash.com/photo-1601493700631-2b16ec4b4716?w=1200&q=80', now() - interval '2 days'),
('disciplinare-grano-antico', 'Nuovo disciplinare per il grano antico dei Sicani', 'Approvate le linee guida per la tutela della biodiversità cerealicola: Perciasacchi, Tumminia e Maiorca al centro del progetto.', E'## Tutela e trasparenza\n\nIl nuovo disciplinare, frutto di due anni di lavoro con l''Università di Palermo, definisce gli standard per la **coltivazione, molitura e tracciabilità** delle varietà antiche di grano coltivate sui Monti Sicani.\n\n### Punti chiave\n\n1. Sementi certificate da banca del germoplasma\n2. Molitura esclusivamente a pietra naturale\n3. Tracciabilità completa via QR code\n\nIl disciplinare è disponibile in versione integrale per tutti i soci.', 'Istituzionale', 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=1200&q=80', now() - interval '7 days'),
('caseifici-aperti-maggio', 'Caseifici aperti: un viaggio tra le antiche tradizioni dei Sicani', 'Dieci produttori apriranno le porte delle loro aziende per degustazioni guidate e laboratori sul formaggio a latte crudo.', E'## L''evento\n\nDomenica **12 maggio** torna ''Caseifici Aperti'', l''evento che porta i visitatori dentro le aziende casearie dei Monti Sicani per scoprire da vicino la lavorazione del **formaggio a latte crudo**.\n\n### Cosa aspettarsi\n\n- Visite guidate ai caseifici\n- Degustazioni di pecorino, vastedda e ricotta fresca\n- Laboratori per bambini\n- Incontro con i pastori\n\nLa partecipazione è gratuita previa prenotazione sul sito.', 'Eventi', 'https://images.unsplash.com/photo-1486297678162-eb2a19b0a32d?w=1200&q=80', now() - interval '14 days');
